List<List<String>> groupAnagrams(String[] words) {
    Map<String, List<String>> groups = new HashMap<>();
    for (String w : words) {
        int[] count = new int[26];
        for (char c : w.toCharArray()) count[c - 'a']++;
        StringBuilder key = new StringBuilder();       // O(L) count key
        for (int n : count) key.append('#').append(n);
        groups.computeIfAbsent(key.toString(), k -> new ArrayList<>()).add(w);
    }
    return new ArrayList<>(groups.values());
}

// ["eat","tea","tan","ate"]
// eat,tea,ate -> same count key -> one group; tan -> its own group
// result: [[eat,tea,ate],[tan]]
```

