char firstUniq(String s) {
    int[] count = new int[256];
    for (char c : s.toCharArray()) count[c]++;   // pass 1: count
    for (char c : s.toCharArray())               // pass 2: scan IN ORDER
        if (count[c] == 1) return c;
    return '_';                                  // none unique
}

// s = "leetcode"
// counts: l=1,e=3,t=1,c=1,o=1,d=1
// pass 2 scans l(1) -> return 'l'
```

