boolean canFormPalindrome(String s) {
    Set<Character> odd = new HashSet<>();
    for (char c : s.toCharArray()) {
        if (!odd.add(c)) odd.remove(c);   // toggle: in on odd, out on even
    }
    return odd.size() <= 1;               // at most one odd count
}

// s = "aabbc": a even, b even, c odd -> odd={c}, size 1 -> true (e.g. abcba)
// s = "aabbcd": c, d odd -> odd={c,d}, size 2 -> false
```
The toggle leaves exactly the odd-count characters in the set.
